import 'dart:io';

import 'package:flutter/painting.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:ironpeak_mobile/theme/launcher_icons.dart';
import 'package:ironpeak_mobile/widgets/ironpeak_logo.dart';

/// The Android launcher resources are GENERATED by tool/generate_icons.dart
/// from lib/theme/launcher_icons.dart and lib/widgets/ironpeak_logo.dart.
/// Nothing compiles them against the Dart until a (slow) Gradle build, and a
/// stale or hand-edited file only shows up on a phone -- as a missing icon,
/// a wrong color or, worst case, no launcher entry at all. These tests fail
/// as soon as the generated files and their sources disagree; the fix is
/// always `flutter test tool/generate_icons.dart`.
const String _res = 'android/app/src/main/res';

String _read(String path) {
  final file = File(path);
  expect(file.existsSync(), isTrue, reason: '$path is missing (run from mobile/)');
  return file.readAsStringSync();
}

String _hex(Color c) =>
    '#${c.toARGB32().toRadixString(16).padLeft(8, '0').toUpperCase()}';

/// The `<activity-alias ...>` blocks of the release overlay, by name.
Map<String, String> _aliases(String manifest) {
  final blocks = <String, String>{};
  for (final m in RegExp(r'<activity-alias\b(.*?)</activity-alias>', dotAll: true)
      .allMatches(manifest)) {
    final block = m.group(1)!;
    final name = RegExp(r'android:name="([^"]+)"').firstMatch(block)!.group(1)!;
    expect(blocks.containsKey(name), isFalse, reason: 'alias $name declared twice');
    blocks[name] = block;
  }
  return blocks;
}

void main() {
  test('every variant has its adaptive icon and foreground', () {
    for (final v in LauncherIcons.all) {
      final icon = _read('$_res/mipmap-anydpi-v26/${v.androidIcon}.xml');
      expect(icon, contains('@color/ic_launcher_backdrop_${v.backdrop.name}'));
      expect(icon, contains('@drawable/ic_launcher_foreground_${v.id}'));
      expect(icon, contains('@drawable/ic_launcher_monochrome'));

      final foreground = _read('$_res/drawable/ic_launcher_foreground_${v.id}.xml');
      expect(foreground, contains('android:fillColor="${_hex(v.glyph)}"'), reason: v.id);
      for (final data in [IronpeakMark.bar, IronpeakMark.plates, IronpeakMark.peak]) {
        expect(foreground, contains(data), reason: v.id);
      }
    }
  });

  test('the backdrop colors and the themed layer match the sources', () {
    final colors = _read('$_res/values/ic_launcher_backdrops.xml');
    expect(colors, contains(_hex(LauncherIcons.lightBackdrop)));
    expect(colors, contains(_hex(LauncherIcons.darkBackdrop)));

    final mono = _read('$_res/drawable/ic_launcher_monochrome.xml');
    for (final data in [IronpeakMark.bar, IronpeakMark.plates, IronpeakMark.peak]) {
      expect(mono, contains(data));
    }
  });

  test('the release overlay declares exactly one enabled alias per variant', () {
    final manifest = _read('android/app/src/release/AndroidManifest.xml');
    final aliases = _aliases(manifest);
    expect(aliases.keys.toSet(),
        LauncherIcons.all.map((v) => v.androidAlias).toSet());

    for (final v in LauncherIcons.all) {
      final block = aliases[v.androidAlias]!;
      expect(block, contains('android:icon="@mipmap/${v.androidIcon}"'));
      expect(block, contains('android:targetActivity="${LauncherIcons.androidActivity}"'));
      expect(block, contains('android:exported="true"'));
      expect(block, contains('android.intent.category.LAUNCHER'));
      expect(block, contains('android:enabled="${v == LauncherIcons.defaultVariant}"'),
          reason: v.id);
    }

    // The real activity's own launcher filter goes away in release builds.
    expect(
      manifest,
      matches(RegExp(
        '<activity android:name="${RegExp.escape(LauncherIcons.androidActivity)}">\\s*'
        '<intent-filter tools:node="removeAll" />',
      )),
    );
  });

  test('the main manifest launches the activity every alias targets', () {
    final manifest = _read('android/app/src/main/AndroidManifest.xml');
    expect(manifest, contains('android:name="${LauncherIcons.androidActivity}"'));
    // Debug builds have no aliases: flutter run needs a real launcher
    // activity, so the LAUNCHER filter stays here and only the release
    // overlay removes it.
    expect(manifest, isNot(contains('<activity-alias')));
    expect(manifest, contains('android.intent.category.LAUNCHER'));
  });

  test('the launch animation plays the same script as the in-app logo', () {
    final light = _read('$_res/drawable/ic_splash_animated.xml');
    final dark = _read('$_res/drawable-night/ic_splash_animated.xml');
    expect(light, contains(_hex(LauncherIcons.glyphColor(
        LauncherIcons.defaultVariant.hue, IconBackdrop.light))));
    expect(dark, contains(_hex(LauncherIcons.glyphColor(
        LauncherIcons.defaultVariant.hue, IconBackdrop.dark))));

    int ms(double seconds) => (seconds * 1000).round();
    for (final xml in [light, dark]) {
      for (final (target, timing) in [
        ('bar', IronpeakMark.barGrow),
        ('plates', IronpeakMark.platesSnap),
        ('peak', IronpeakMark.peakRiseTiming),
      ]) {
        final block = RegExp('<target android:name="$target">(.*?)</target>', dotAll: true)
            .firstMatch(xml)!
            .group(1)!;
        final (start, seconds) = timing;
        expect(block, contains('android:duration="${ms(seconds)}"'), reason: target);
        if (start > 0) {
          expect(block, contains('android:startOffset="${ms(start)}"'), reason: target);
        }
      }
      // Under Android 12's 1000 ms cap for splash animations.
      final ends = [IronpeakMark.barGrow, IronpeakMark.platesSnap, IronpeakMark.peakRiseTiming]
          .map((t) => t.$1 + t.$2);
      expect(ends.reduce((a, b) => a > b ? a : b), lessThanOrEqualTo(1.0));
    }
  });
}
